<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfilePhoneNumberVerifiedAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfilePhoneNumberVerifiedAccessor trait.
 *
 * Covers null default, string/VO assignment via withPhoneNumberVerified,
 * getPhoneNumberVerified/phoneNumberVerified accessors, and isPhoneNumberVerifiedChanged with/without original.
 */
class UserProfilePhoneNumberVerifiedAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withPhoneNumberVerified creates a new instance with the PhoneNumberVerified set
     * from a string value, and getPhoneNumberVerified returns the primitive string.
     */
    public function testWithPhoneNumberVerifiedFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePhoneNumberVerifiedAccessorUnitTest();

        // Act
        $result = $holder->withPhoneNumberVerified(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isPhoneNumberVerified());
    }
    /**
     * Asserts that withphoneNumberVerified has access to the value object
     * from a string value, and getPhoneNumberVerified returns the primitive string.
     */
    public function testWithPhoneNumberVerifiedFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePhoneNumberVerifiedAccessorUnitTest();

        // Act
        $result = $holder->withPhoneNumberVerified(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->phoneNumberVerified()->value());
    }
    public function testChangedPhoneNumberVerified(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePhoneNumberVerifiedAccessorUnitTest();
        $original = $holder->withPhoneNumberVerified(true);
        $same = $holder->withPhoneNumberVerified(true);
        $modified = $holder->withPhoneNumberVerified(false);

        // Act
        $unchanged = $holder->isPhoneNumberVerifiedChanged();
        $withSame = $original->isPhoneNumberVerifiedChanged($same);
        $withDiferent = $original->isPhoneNumberVerifiedChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfilePhoneNumberVerifiedAccessorUnitTest
{
    use UserProfilePhoneNumberVerifiedAccessor;
}
